set-variable.value:
@{
            var input = context.Request.Body.As<JObject>(preserveContent: true);
            var o = new JObject();
            o["id"] = context.Request.MatchedParameters["id"];
            o["name"] = input["name"];
            o["email"] = input["email"];
            if (input["city"] != null) { o["city"] = input["city"]; }
            return o.ToString();
        }

inbound.set-body:
@{
            var o = JObject.Parse((string)context.Variables["replaceBody"]);
            var e = new JObject();
            e["PartitionKey"] = "customer";
            e["RowKey"] = o["id"];
            e["name"] = o["name"];
            e["email"] = o["email"];
            if (o["city"] != null) { e["city"] = o["city"]; }
            return e.ToString();
        }
